extends Node3D
## Builds the authored greybox arena and wires layers per launch config.
##
## Play mode (no args): pilot + mg_west + cc_center sockets, mouse-look TPS.
## Scenario mode: godot --headless --path . -- --scenario=A|B|C|D|E
##
## All placement below is authored design data — no freeform building.

const EnemyBase := preload("res://combat/src/enemies/enemy_base.gd")
const PressureEnemy := preload("res://combat/src/enemies/pressure_enemy.gd")
const ArmoredEnemy := preload("res://combat/src/enemies/armored_enemy.gd")
const HarasserEnemy := preload("res://combat/src/enemies/harasser_enemy.gd")
const MGTurret := preload("res://combat/src/turrets/mg_turret.gd")
const CCTurret := preload("res://combat/src/turrets/cc_turret.gd")
const TurretSocket := preload("res://combat/src/turrets/turret_socket.gd")
const CoreNode := preload("res://combat/src/core/core_node.gd")
const SupplyPoint := preload("res://combat/src/supply/supply_point.gd")
const PilotAvatar := preload("res://combat/src/pilot/pilot_avatar.gd")
const Autopilot := preload("res://combat/src/autopilot/autopilot.gd")
const ScenarioRunner := preload("res://combat/scenarios/scenario_runner.gd")
const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")
const Stats := preload("res://combat/data/combat_stats.gd")

const ARENA := {
	"size": 80.0,
	"core": Vector3(0, 0, 0),
	"pilot_spawn": Vector3(0, 0.1, 12),
	"supply": Vector3(-14, 0, 16),
	"sockets": [
		{"name": "mg_west", "kind": "mg", "pos": Vector3(-10, 0, -10)},
		{"name": "mg_east", "kind": "mg", "pos": Vector3(10, 0, -10)},
		{"name": "cc_center", "kind": "cc", "pos": Vector3(0, 0, -14)},
	],
	"lanes": [Vector3(-16, 0.1, -34), Vector3(0, 0.1, -36), Vector3(16, 0.1, -34)],
}

var core: Node3D
var supply: Node3D
var pilot = null
var sockets := {}
var runner = null
var _hud: Label
var _spawn_timer := 5.0
var _spawn_interval := 3.2
var _role_cycle := [0, 0, 0, 2, 0, 0, 1]
var _lane_cycle := [0, 1, 2, 1]
var _spawn_i := 0


func _ready() -> void:
	EnemyBase.stats = Stats.ensure()
	_build_environment()
	core = CoreNode.new()
	add_child(core)
	core.position = ARENA.core
	supply = SupplyPoint.new()
	add_child(supply)
	supply.position = ARENA.supply
	for def in ARENA.sockets:
		var s := TurretSocket.new()
		s.socket_name = def.name
		s.kind = def.kind
		s.position = def.pos
		add_child(s)
		sockets[def.name] = s

	for a in OS.get_cmdline_user_args():
		if a.begins_with("--scenario="):
			runner = ScenarioRunner.new()
			runner.scenario_id = a.substr(11)
			add_child(runner)
			return
	_setup_play()


func _setup_play() -> void:
	populate_socket("mg_west")
	populate_socket("cc_center")
	spawn_pilot(false)
	_build_hud()


func populate_socket(sname: String) -> void:
	var s = sockets.get(sname)
	if s == null or s.is_populated():
		return
	if s.kind == "mg":
		s.populate(MGTurret)
	else:
		s.populate(CCTurret)


func active_turrets() -> Array:
	var out := []
	for s in sockets.values():
		if s.is_populated():
			out.append(s.turret)
	return out


func spawn_pilot(with_autopilot: bool) -> void:
	pilot = PilotAvatar.new()
	pilot.controlled_locally = not with_autopilot
	add_child(pilot)
	pilot.position = ARENA.pilot_spawn
	pilot.state.position = ARENA.pilot_spawn
	pilot.core = core
	pilot.supply = supply
	pilot.turrets = active_turrets()
	if with_autopilot:
		var ap := Autopilot.new()
		ap.pilot = pilot
		ap.core = core
		ap.supply = supply
		ap.turrets = pilot.turrets
		pilot.add_child(ap)
		pilot.autopilot = ap


func refresh_pilot_refs() -> void:
	if pilot != null:
		var fresh := active_turrets()
		pilot.turrets.clear()
		pilot.turrets.append_array(fresh)


func spawn_enemy(role: int, pos: Vector3) -> void:
	var e = null
	match role:
		0: e = PressureEnemy.new()
		1: e = ArmoredEnemy.new()
		2: e = HarasserEnemy.new()
	e.core = core
	e.target = core
	add_child(e)
	e.global_position = pos


func _physics_process(dt: float) -> void:
	if runner != null:
		return
	if not core.dead:
		_trickle_spawn(dt)
	var alive := get_tree().get_nodes_in_group("enemies").size()
	Metrics.inst().tick(dt, alive)
	if core.dead:
		Metrics.inst().outcome = "core_lost"


func _trickle_spawn(dt: float) -> void:
	_spawn_timer -= dt
	if _spawn_timer > 0.0:
		return
	_spawn_timer = _spawn_interval
	var role: int = _role_cycle[_spawn_i % _role_cycle.size()]
	spawn_enemy(role, ARENA.lanes[_lane_cycle[_spawn_i % _lane_cycle.size()]])
	_spawn_i += 1
	if _spawn_i % 8 == 0:
		_spawn_interval = maxf(1.6, _spawn_interval - 0.25)


func _input(event: InputEvent) -> void:
	if event is InputEventKey and event.pressed and event.keycode == KEY_R and core != null and core.dead:
		get_tree().reload_current_scene()


func _process(_dt: float) -> void:
	if _hud != null and pilot != null:
		_hud.text = _hud_text()


func _hud_text() -> String:
	var st = pilot.state
	var m = Metrics.inst()
	var lines := ["CORE %d%%   HP %d   ВРАГОВ %d" % [
		int(m.core_hp / maxf(m.core_max, 1.0) * 100.0),
		int(st.health),
		get_tree().get_nodes_in_group("enemies").size()]]
	for t in active_turrets():
		lines.append("%s патроны %d/%d%s" % [t.kind.to_upper(), t.ammo, t.ammo_max,
				" — УНИЧТОЖЕНА" if t.destroyed else (" — ПУСТА, нужен пакет!" if t.ammo == 0 else "")])
	if st.carrying_pack:
		var needy = _nearest_hungry_turret()
		if needy != null:
			lines.append("ПАКЕТ: E у турели (%d м) — зарядить" % int(pilot.global_position.distance_to(needy.global_position)))
		else:
			lines.append("ПАКЕТ: турели полны")
	else:
		if supply != null and is_instance_valid(supply) and supply.available():
			lines.append("E у ящика (%d м) — взять пакет" % int(pilot.global_position.distance_to(supply.global_position)))
		else:
			lines.append("ЯЩИК УНИЧТОЖЕН — пополнения нет")
	if core.dead:
		lines.append("")
		lines.append("ЯДРО ПОТЕРЯНО — R: заново")
	return "\n".join(lines)


func _nearest_hungry_turret():
	var best = null
	var best_d := INF
	for t in active_turrets():
		if t.ammo < t.ammo_max:
			var d: float = pilot.global_position.distance_to(t.global_position)
			if d < best_d:
				best_d = d
				best = t
	return best


func _build_hud() -> void:
	var layer := CanvasLayer.new()
	add_child(layer)
	_hud = Label.new()
	_hud.position = Vector2(16, 16)
	_hud.custom_minimum_size = Vector2(500, 160)
	layer.add_child(_hud)

	var hint := Label.new()
	hint.text = "WASD бег · SPACE прыжок · SHIFT рывок · ЛКМ огонь · E взять/зарядить · R заново"
	hint.position = Vector2(16, 690)
	layer.add_child(hint)


func _build_environment() -> void:
	var floor_body := StaticBody3D.new()
	floor_body.collision_layer = 1
	var fmesh := MeshInstance3D.new()
	var plane := PlaneMesh.new()
	plane.size = Vector2(ARENA.size, ARENA.size)
	fmesh.mesh = plane
	floor_body.add_child(fmesh)
	var cs := CollisionShape3D.new()
	var shape := BoxShape3D.new()
	shape.size = Vector3(ARENA.size, 0.2, ARENA.size)
	cs.shape = shape
	cs.position.y = -0.1
	floor_body.add_child(cs)
	var fm := StandardMaterial3D.new()
	fm.albedo_color = Color(0.22, 0.24, 0.26)
	fmesh.material_override = fm
	add_child(floor_body)

	var light := DirectionalLight3D.new()
	light.rotation_degrees = Vector3(-55, -30, 0)
	light.shadow_enabled = true
	add_child(light)

	var env := WorldEnvironment.new()
	var e := Environment.new()
	e.background_mode = Environment.BG_SKY
	var sky := Sky.new()
	sky.sky_material = ProceduralSkyMaterial.new()
	e.sky = sky
	e.ambient_light_source = Environment.AMBIENT_SOURCE_SKY
	env.environment = e
	add_child(env)

extends Node
## Scripted pilot brain for scenarios A/D/E. Emits standard PilotCommands that
## flow through the same motor path a Netcode Agent would drive. Perfect-aim,
## perfect-info model ON PURPOSE: scenarios measure layer capability, not
## human skill variance.

const ActorCommand := preload("res://actor/actor_command.gd")
const PilotMotor := preload("res://combat/src/pilot/pilot_motor.gd")

var pilot
var core: Node3D
var supply: Node3D
var turrets: Array = []
var supply_duty := true
var aim_error_deg := 0.0
var ferrying := false

var _last_hp := 100.0


func tick(_dt: float) -> ActorCommand:
	var cmd := ActorCommand.new()
	var st = pilot.state
	if not st.alive:
		return cmd

	var focus = _choose_focus()
	ferrying = false
	var goal := _hold_point()
	var want_pickup := false
	var want_deposit := false

	var needy = _neediest_turret()
	var sieging: bool = focus != null and focus.has_method("cc_state") \
			and focus.cc_state() == "armored_siege"
	if supply_duty and not sieging and needy != null \
			and float(needy.ammo) / maxf(float(needy.ammo_max), 1.0) < 0.3:
		if not st.carrying_pack and supply != null and supply.available():
			goal = supply.global_position
			want_pickup = true
			ferrying = true
		elif st.carrying_pack:
			goal = needy.global_position
			want_deposit = true
			ferrying = true

	var to_goal: Vector3 = goal - st.position
	to_goal.y = 0.0
	var stop_dist := 1.8 if (want_pickup or want_deposit) else 5.0
	var traveling := to_goal.length() > stop_dist

	if traveling:
		cmd.mv = Vector2(0.0, -1.0) # canon: y back-positive, -1 = forward
		_steer_yaw(cmd, st, to_goal.normalized())
	else:
		if want_pickup and supply != null \
				and st.position.distance_to(supply.global_position) <= supply.INTERACT_RADIUS:
			cmd.interact = true
		if want_deposit and needy != null \
				and st.position.distance_to(needy.global_position) <= 3.0 and needy.ammo < needy.ammo_max:
			cmd.interact = true
		if focus != null:
			var aim_point: Vector3
			if focus.has_method("weakpoint_pos"):
				aim_point = focus.weakpoint_pos()
			else:
				aim_point = focus.global_position + Vector3.UP * 0.8
			if aim_error_deg > 0.0:
				var dist: float = aim_point.distance_to(st.position)
				var err := deg_to_rad(aim_error_deg) * dist
				aim_point += Vector3(randf_range(-1, 1), randf_range(-1, 1), randf_range(-1, 1)).normalized() * err
			var aim_dir: Vector3 = aim_point - st.position
			aim_dir.y = 0.0
			if aim_dir.length() > 0.1:
				_steer_yaw(cmd, st, aim_dir.normalized())
				_aim_at(cmd, st, aim_point)
				cmd.fire_p = true

	if st.health < _last_hp - 0.5:
		cmd.dodge = true
	_last_hp = st.health
	return cmd


func _steer_yaw(cmd: ActorCommand, st, dir: Vector3) -> void:
	var wanted := PilotMotor.yaw_toward(st.yaw, dir)
	var delta := wrapf(wanted - st.yaw, -PI, PI)
	cmd.yaw_delta = clampf(-delta / ActorCommand.INPUT_LOOK_SENSITIVITY, -60.0, 60.0)


func _aim_at(cmd: ActorCommand, st, world_target: Vector3) -> void:
	var eye: Vector3 = st.position + Vector3(0, 1.75, 0)
	var to: Vector3 = world_target - eye
	var horiz := sqrt(to.x * to.x + to.z * to.z)
	var wanted_pitch := atan2(to.y, maxf(horiz, 0.001))
	var delta: float = wanted_pitch - st.pitch
	cmd.pitch_delta = clampf(-delta / ActorCommand.INPUT_LOOK_SENSITIVITY, -60.0, 60.0)


func _choose_focus():
	var harassers := []
	var armored := []
	var pressures := []
	for e in pilot.get_tree().get_nodes_in_group("enemies"):
		match e.role:
			2: harassers.append(e)
			1: armored.append(e)
			0: pressures.append(e)
	if not harassers.is_empty():
		return _closest(harassers)
	if not armored.is_empty():
		return _closest(armored)
	return _closest(pressures)


func _closest(list: Array):
	var best = null
	var best_d := INF
	for e in list:
		var d: float = core.global_position.distance_to(e.global_position)
		if d < best_d:
			best_d = d
			best = e
	return best


func _neediest_turret():
	var best = null
	var best_frac := 1.01
	for t in turrets:
		if not is_instance_valid(t) or t.destroyed:
			continue
		var frac := float(t.ammo) / maxf(float(t.ammo_max), 1.0)
		if frac < best_frac:
			best_frac = frac
			best = t
	return best


func _hold_point() -> Vector3:
	var nearest = null
	var best_d := INF
	for e in pilot.get_tree().get_nodes_in_group("enemies"):
		var d: float = core.global_position.distance_to(e.global_position)
		if d < best_d:
			best_d = d
			nearest = e
	if nearest == null:
		return core.global_position + Vector3(0, 0, 7)
	var dir: Vector3 = nearest.global_position - core.global_position
	dir.y = 0.0
	if dir.length() < 0.5:
		return core.global_position + Vector3(0, 0, 7)
	return core.global_position + dir.normalized() * 6.5

extends StaticBody3D
## Defend objective. Accepts only ENEMY-source events in the lab (friendly fire
## off by design until the Mech Lab needs it). Death signal ends the scenario.

const DamageEvent := preload("res://combat/src/combat/damage_contract.gd")
const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")
const Stats := preload("res://combat/data/combat_stats.gd")
const ModelLib := preload("res://combat/src/visuals/model_lib.gd")

signal died

var hp := 1000.0
var max_hp := 1000.0
var dead := false


func _ready() -> void:
	max_hp = Stats.ensure().core_hp
	hp = max_hp
	Metrics.inst().core_max = max_hp
	Metrics.inst().core_hp = hp
	add_to_group("core")

	if ModelLib.attach_sized(self, "SM_Prop_PowerGenerator_01.fbx",
			Color(0.3, 0.5, 0.95), Vector3.ZERO, 2.2):
		pass
	else:
		var mesh := MeshInstance3D.new()
		var cyl := CylinderMesh.new()
		cyl.top_radius = 1.6
		cyl.bottom_radius = 2.0
		cyl.height = 2.4
		mesh.mesh = cyl
		mesh.position.y = 1.2
		var m := StandardMaterial3D.new()
		m.albedo_color = Color(0.3, 0.5, 0.95)
		m.emission_enabled = true
		m.emission = Color(0.05, 0.15, 0.4)
		mesh.material_override = m
		add_child(mesh)

	var cs := CollisionShape3D.new()
	var shape := CylinderShape3D.new()
	shape.radius = 1.8
	shape.height = 2.4
	cs.shape = shape
	cs.position.y = 1.2
	add_child(cs)


func take_damage(evt) -> void:
	if dead or evt.source != DamageEvent.Source.ENEMY:
		return
	hp -= evt.amount
	Metrics.inst().core_damage_taken += evt.amount
	Metrics.inst().core_hp = hp
	if hp <= 0.0:
		hp = 0.0
		dead = true
		died.emit()


func packed_state() -> Dictionary:
	return {"hp_frac": snappedf(hp / maxf(max_hp, 1.0), 0.01), "dead": dead}

extends CharacterBody3D
## Shared enemy actor. Lab movement is straight-line seek (open arena); the
## Crowd Lab replaces internals with flow-field data-oriented mass behind this
## same interface: take_damage / apply_slow / packed_state / groups.

const DamageEvent := preload("res://combat/src/combat/damage_contract.gd")
const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")

enum Role { PRESSURE, ARMORED, HARASSER }

static var stats = null

var role: int = Role.PRESSURE
var max_hp := 60.0
var hp := 60.0
var speed := 3.2
var slow_factor := 1.0
var slow_left := 0.0
var target: Node3D = null
var core: Node3D = null
var _melee_cd := 0.0


static func damage_multiplier(p_role: int, p_source: int, p_weakpoint: bool) -> float:
	if p_role == Role.ARMORED:
		if p_weakpoint:
			return stats.weakpoint_bonus if stats != null else 2.5
		var s = stats
		match p_source:
			DamageEvent.Source.MG_TURRET:
				return s.shell_mg if s != null else 0.12
			DamageEvent.Source.CC_TURRET:
				return 0.5
			DamageEvent.Source.PILOT_GUN:
				return s.shell_pilot if s != null else 0.35
			DamageEvent.Source.MECH_ROTARY:
				return 0.5
			_:
				return 1.0
	return 1.0


static func role_name_of(p_role: int) -> String:
	return ["pressure", "armored", "harasser"][p_role]


func role_name() -> String:
	return role_name_of(role)


func _physics_process(dt: float) -> void:
	if is_queued_for_deletion():
		return
	if slow_left > 0.0:
		slow_left -= dt
		Metrics.inst().add_cc_time(dt)
		if slow_left <= 0.0:
			slow_factor = 1.0
	if role == Role.HARASSER:
		_brain(dt)
		return
	if target == null or not is_instance_valid(target):
		return
	var to: Vector3 = target.global_position - global_position
	to.y = 0.0
	var dist := to.length()
	if _combat_behaviour(dist, dt):
		return
	var dir := to / maxf(dist, 0.001)
	velocity = dir * speed * slow_factor
	_face(dir)
	move_and_slide()


func _combat_behaviour(_dist: float, _dt: float) -> bool:
	return false


func _brain(_dt: float) -> void:
	pass


func take_damage(evt) -> void:
	if hp <= 0.0:
		return
	var mult := damage_multiplier(role, evt.source, evt.weakpoint)
	var eff: float = evt.amount * mult
	hp -= eff
	var victim := role_name()
	Metrics.inst().log_damage(evt, victim, eff)
	if hp <= 0.0:
		Metrics.inst().log_kill(evt.source_name(), victim)
		if evt.source == DamageEvent.Source.PILOT_GUN and role != Role.PRESSURE:
			Metrics.inst().priority_kill()
		queue_free()


func apply_slow(factor: float, duration: float) -> void:
	slow_factor = factor
	slow_left = maxf(slow_left, duration)
	var m = Metrics.inst()
	m.cc_applied()
	var st := cc_state()
	m.cc_apps_by_state[st] = m.cc_apps_by_state.get(st, 0) + 1


func cc_state() -> String:
	return role_name()


func nearest_pilot() -> Node3D:
	for p in get_tree().get_nodes_in_group("player"):
		if is_instance_valid(p) and p.state != null and p.state.alive:
			return p
	return null


func try_melee(dt: float, range_m: float, damage: float, interval: float) -> bool:
	_melee_cd = maxf(0.0, _melee_cd - dt)
	if _melee_cd > 0.0:
		return false
	var pilot := nearest_pilot()
	if pilot == null:
		return false
	var to: Vector3 = pilot.global_position - global_position
	to.y = 0.0
	if to.length() > range_m:
		return false
	_melee_cd = interval
	_face(to.normalized())
	DamageEvent.apply(pilot, DamageEvent.new(damage, DamageEvent.Source.ENEMY,
			get_instance_id(), pilot.global_position))
	return true


func packed_state() -> Dictionary:
	return {
		"id": get_instance_id(),
		"role": role_name(),
		"hp_frac": snappedf(hp / maxf(max_hp, 1.0), 0.01),
		"pos": [global_position.x, global_position.y, global_position.z],
		"slowed": slow_left > 0.0,
	}


func _face(dir: Vector3) -> void:
	if dir.length_squared() > 0.0001:
		rotation.y = atan2(-dir.x, -dir.z)


func _die_quiet() -> void:
	queue_free()

extends "res://combat/src/enemies/enemy_base.gd"
## Harasser: fast purple wedge that orbits a victim (turret > supply > pilot),
## lobs slow projectiles and evades when the pilot closes in. Breaks static
## defensive positions by threatening infrastructure. Simple explicit states —
## no behavior-tree dependency at this scale (see README LimboAI decision).

const HarasserProjectile := preload("res://combat/src/enemies/harasser_projectile.gd")
const ModelLib := preload("res://combat/src/visuals/model_lib.gd")

enum HState { APPROACH, ATTACK, EVADE }

const STANDOFF := 11.0
const EVADE_DIST := 6.0

var h_state: int = HState.APPROACH
var victim: Node3D = null
var orbit_angle := 0.0
var orbit_dir := 1.0
var proj_cd := 1.5
var evade_left := 0.0


func _init() -> void:
	role = Role.HARASSER


func _ready() -> void:
	max_hp = stats.harasser_hp
	hp = max_hp
	speed = stats.harasser_speed
	add_to_group("enemies")
	Metrics.inst().spawned_by_role["harasser"] += 1
	orbit_angle = randf() * TAU
	orbit_dir = 1.0 if randf() < 0.5 else -1.0
	_pick_victim()

	if not ModelLib.attach_sized(self, "SM_Prop_Drone_03.fbx",
			Color(0.6, 0.25, 0.85), Vector3(0, 0.6, 0), 1.9):
		var mesh := MeshInstance3D.new()
		var prism := PrismMesh.new()
		prism.size = Vector3(1.0, 0.8, 1.8)
		mesh.mesh = prism
		mesh.position.y = 0.6
		var m := StandardMaterial3D.new()
		m.albedo_color = Color(0.6, 0.25, 0.85)
		m.emission_enabled = true
		m.emission = Color(0.2, 0.02, 0.35)
		mesh.material_override = m
		add_child(mesh)

	var cs := CollisionShape3D.new()
	var shape := BoxShape3D.new()
	shape.size = Vector3(1.0, 0.8, 1.8)
	cs.shape = shape
	cs.position.y = 0.6
	add_child(cs)


func _pick_victim() -> void:
	var turrets := get_tree().get_nodes_in_group("turrets")
	for t in turrets:
		if is_instance_valid(t) and not t.destroyed:
			victim = t
			return
	var supplies := get_tree().get_nodes_in_group("supply")
	if not supplies.is_empty():
		victim = supplies[0]
		return
	var players := get_tree().get_nodes_in_group("player")
	if not players.is_empty():
		victim = players[0]
	else:
		victim = core


func _victim_pos() -> Vector3:
	if victim != null and is_instance_valid(victim):
		return victim.global_position
	_pick_victim()
	if victim != null and is_instance_valid(victim):
		return victim.global_position
	return global_position


func _brain(dt: float) -> void:
	match h_state:
		HState.APPROACH:
			_move_toward(_victim_pos(), dt)
			if global_position.distance_to(_victim_pos()) <= STANDOFF + 1.5:
				h_state = HState.ATTACK
		HState.ATTACK:
			_orbit(dt)
			proj_cd -= dt
			if proj_cd <= 0.0:
				proj_cd = stats.harasser_proj_interval / maxf(slow_factor, 0.01)
				_fire()
			if victim != null and is_instance_valid(victim) and victim.is_in_group("player") \
					and global_position.distance_to(victim.global_position) < EVADE_DIST:
				h_state = HState.EVADE
				evade_left = 1.6
		HState.EVADE:
			evade_left -= dt
			var away: Vector3 = global_position - _victim_pos()
			away.y = 0.0
			_move_toward(global_position + away.normalized() * 4.0, dt)
			if evade_left <= 0.0:
				h_state = HState.ATTACK
	if victim == null or not is_instance_valid(victim) or ("destroyed" in victim and victim.destroyed):
		h_state = HState.APPROACH
		_pick_victim()


func _move_toward(dest: Vector3, dt: float) -> void:
	var to := dest - global_position
	to.y = 0.0
	var dist := to.length()
	if dist < 0.1:
		velocity = Vector3.ZERO
		return
	var dir := to / dist
	velocity = dir * speed * slow_factor * minf(dist, 1.0)
	_face(dir)
	move_and_slide()


func _orbit(dt: float) -> void:
	orbit_angle += dt * 0.9 * orbit_dir
	var ring := _victim_pos() + Vector3(cos(orbit_angle), 0.0, sin(orbit_angle)) * STANDOFF
	ring.y = global_position.y
	_move_toward(ring, dt)


func _fire() -> void:
	if victim == null or not is_instance_valid(victim):
		return
	var p := HarasserProjectile.new()
	get_parent().add_child(p)
	p.launch(global_position + Vector3.UP * 0.7, victim)

