extends CharacterBody3D
## Composition root for the pilot. Wires command sources (device input,
## autopilot, future Netcode Agent via push_command) into PilotMotor.step,
## resolves collision through this host body, then mirrors PilotState out to
## presentation and weapon. The loop never reads devices directly.

const ActorCommand := preload("res://actor/actor_command.gd")
const PilotState := preload("res://combat/src/pilot/pilot_state.gd")
const PilotMotor := preload("res://combat/src/pilot/pilot_motor.gd")
const PilotPresentation := preload("res://combat/src/pilot/pilot_presentation.gd")
const PilotInput := preload("res://combat/src/pilot/pilot_input.gd")
const PilotWeapon := preload("res://combat/src/pilot/pilot_weapon.gd")
const DamageEvent := preload("res://combat/src/combat/damage_contract.gd")
const Metrics := preload("res://combat/src/metrics/combat_metrics.gd")
const Stats := preload("res://combat/data/combat_stats.gd")

var state := PilotState.new()
var weapon: PilotWeapon
var presentation  # : PilotPresentation
var input_adapter: Node
var autopilot: Node = null
var controlled_locally := true
var core: Node3D = null
var supply: Node3D = null
var turrets: Array = []
var _queue: Array = []
var _respawn_left := 0.0


func _ready() -> void:
	add_to_group("player")
	weapon = PilotWeapon.new()
	var cs := CollisionShape3D.new()
	var cap := CapsuleShape3D.new()
	cap.radius = 0.4
	cap.height = 1.8
	cs.shape = cap
	cs.position.y = 0.9
	add_child(cs)

	presentation = PilotPresentation.new()
	add_child(presentation)
	presentation.setup(get_rid())
	presentation.camera.make_current()

	if controlled_locally:
		input_adapter = PilotInput.new()
		add_child(input_adapter)
		input_adapter.capture_mouse()


func push_command(cmd) -> void:
	_queue.append(cmd)


func _physics_process(dt: float) -> void:
	var cmd: ActorCommand
	if autopilot != null:
		cmd = autopilot.tick(dt)
	elif not _queue.is_empty():
		cmd = _queue.pop_front()
	elif controlled_locally and input_adapter != null:
		cmd = input_adapter.poll()
	else:
		cmd = ActorCommand.new()

	if not state.alive:
		_respawn_left -= dt
		velocity = Vector3.ZERO
		if _respawn_left <= 0.0:
			state.alive = true
			state.health = 100.0
			presentation.visible = true
		return

	PilotMotor.step(state, cmd, dt, false)
	velocity = state.velocity
	move_and_slide()
	state.position = position
	state.velocity = velocity
	state.grounded = is_on_floor()

	if cmd.interact:
		_handle_interact()
	if cmd.fire_p:
		_try_fire()

	presentation.sync(state)


func _try_fire() -> void:
	if weapon == null:
		return
	var ray = presentation.aim_ray()
	if weapon.try_fire(
			get_world_3d().direct_space_state,
			ray[0], ray[1],
			presentation.muzzle_pos(),
			get_rid(),
			state.fire_cd):
		state.fire_cd = Stats.ensure().pilot_gun_interval
		Metrics.inst().log_shot("pilot_gun")
		if weapon.last_hit_damageable:
			presentation.hit_feedback()
		presentation.tracer(presentation.muzzle_pos(), weapon.last_hit_end)


func _handle_interact() -> void:
	var st = Stats.ensure()
	if not state.carrying_pack:
		if supply != null and is_instance_valid(supply) and not supply.destroyed \
				and global_position.distance_to(supply.global_position) <= supply.INTERACT_RADIUS:
			state.carrying_pack = true
			Metrics.inst().supply_trip()
	else:
		for t in turrets:
			if is_instance_valid(t) and not t.destroyed and t.ammo < t.ammo_max \
					and global_position.distance_to(t.global_position) <= 3.2:
				t.refill(st.pack_size)
				state.carrying_pack = false
				break


func take_damage(evt) -> void:
	if evt.source != DamageEvent.Source.ENEMY or not state.alive:
		return
	state.health -= evt.amount
	Metrics.inst().log_damage(evt, "pilot", evt.amount)
	presentation.damage_flash()
	if state.health <= 0.0:
		state.health = 0.0
		state.alive = false
		state.carrying_pack = false
		_respawn_left = 2.0
		presentation.visible = false
		Metrics.inst().pilot_death()


func packed_state() -> Dictionary:
	return state.packed()

extends Node3D
## Native AnimationTree backend recovered from lab/pilot-locomotion.
## Read-only: PlayerAvatar owns all gameplay truth.

const ASSET := "res://assets/synty/ual_standard.glb"
const FADE := 0.12
const LAND_HOLD := 0.22

var _anim: AnimationPlayer = null
var _tree: AnimationTree = null
var _playback: AnimationNodeStateMachinePlayback = null
var _visual: Node3D = null
var _state := "Idle"
var _was_grounded := true
var _land_left := 0.0


func try_setup() -> bool:
	if not ResourceLoader.exists(ASSET):
		return false
	var ps := load(ASSET)
	if ps == null or not (ps is PackedScene):
		return false
	var inst := (ps as PackedScene).instantiate()
	if inst == null or not (inst is Node3D):
		return false
	_visual = inst as Node3D
	add_child(_visual)
	var players := _visual.find_children("*", "AnimationPlayer", true, false)
	if players.is_empty():
		_visual.queue_free()
		_visual = null
		return false
	_anim = players.front() as AnimationPlayer
	var clips := ["Idle", "Walk", "Jog_Fwd", "Sprint", "Jump_Start", "Jump", "Jump_Land"]
	for clip in clips:
		if not _anim.has_animation(clip):
			push_warning("PilotNativeAnim: missing clip %s" % clip)
			_visual.queue_free()
			_visual = null
			_anim = null
			return false
	_fit_height(_visual, 1.8)
	_build_tree(clips)
	return _tree != null


func _build_tree(clips: Array) -> void:
	var sm := AnimationNodeStateMachine.new()
	for clip in clips:
		var node := AnimationNodeAnimation.new()
		node.animation = StringName(clip)
		sm.add_node(clip, node)
	for from in clips:
		for to in clips:
			if from == to:
				continue
			var transition := AnimationNodeStateMachineTransition.new()
			transition.xfade_time = FADE
			transition.advance_mode = AnimationNodeStateMachineTransition.ADVANCE_MODE_DISABLED
			sm.add_transition(from, to, transition)
	_tree = AnimationTree.new()
	_tree.tree_root = sm
	add_child(_tree)
	_tree.anim_player = _tree.get_path_to(_anim)
	_tree.active = true
	_playback = _tree.get("parameters/playback") as AnimationNodeStateMachinePlayback
	if _playback != null:
		_playback.start("Idle")


func sync(velocity: Vector3, grounded: bool, delta: float) -> void:
	if _tree == null or _playback == null:
		return
	_land_left = maxf(0.0, _land_left - delta)
	var speed := Vector2(velocity.x, velocity.z).length()
	var next := _state
	if grounded:
		if not _was_grounded:
			_land_left = LAND_HOLD
			next = "Jump_Land"
		elif _land_left > 0.0:
			next = "Jump_Land"
		elif speed < 0.35:
			next = "Idle"
		elif speed < 2.5:
			next = "Walk"
		elif speed < 6.0:
			next = "Jog_Fwd"
		else:
			next = "Sprint"
	else:
		next = "Jump_Start" if _was_grounded and velocity.y > 0.0 else "Jump"
	if next != _state:
		_state = next
		_playback.travel(StringName(_state))
	if _anim != null:
		if _state in ["Walk", "Jog_Fwd", "Sprint"] and speed > 0.5:
			_anim.speed_scale = clampf(speed / 3.6, 0.65, 2.2)
		else:
			_anim.speed_scale = 1.0
	_was_grounded = grounded


func backend_name() -> String:
	return "native_animation_tree" if _tree != null else "native_animation_tree_unavailable"


func _fit_height(root: Node3D, target_height: float) -> void:
	var box := AABB()
	var first := true
	for mi in root.find_children("*", "MeshInstance3D", true, false):
		var mesh_instance := mi as MeshInstance3D
		if mesh_instance.mesh == null or not mesh_instance.visible:
			continue
		# Imported GLB meshes commonly sit below Armature/Node3D wrappers. Build
		# the AABB in root-local space, matching the proven locomotion donor;
		# using only mesh_instance.transform mis-sizes nested skeleton scenes.
		var ab := mesh_instance.transform * mesh_instance.mesh.get_aabb()
		var parent := mesh_instance.get_parent()
		while parent != null and parent is Node3D and parent != root:
			ab = (parent as Node3D).transform * ab
			parent = parent.get_parent()
		if first:
			box = ab
			first = false
		else:
			box = box.merge(ab)
	if first or box.size.y <= 0.01:
		return
	var k := target_height / box.size.y
	root.scale = Vector3.ONE * k
	root.position.y = -box.position.y * k
